import ghidra.app.script.GhidraScript;
import ghidra.program.model.listing.*;
import ghidra.program.model.address.*;
import java.io.*;
import java.util.*;
public class N3DRecoverDirectCalls extends GhidraScript {
 public void run() throws Exception {
  int total=0;
  try(PrintWriter p=new PrintWriter(getScriptArgs()[0])){
   p.println("round\tentry\tsource_call\tsource_owner\tcreated");
   for(int round=0;round<8;round++){
    TreeMap<Address,String> seeds=new TreeMap<>();
    for(Instruction i:currentProgram.getListing().getInstructions(true)){
     Function owner=getFunctionContaining(i.getAddress());if(owner==null)continue;
     for(var ref:i.getReferencesFrom())if(ref.getReferenceType().isCall()&&!ref.getReferenceType().toString().contains("COMPUTED")){
      Address a=ref.getToAddress();var block=currentProgram.getMemory().getBlock(a);
      if(block==null||!block.getName().matches("Code[1-4]"))continue;
      if(getFunctionContaining(a)!=null)continue;
      Data data=currentProgram.getListing().getDataAt(a);if(data!=null&&data.isDefined())continue;
      seeds.putIfAbsent(a,i.getAddress()+"\t"+owner.getEntryPoint());
     }
    }
    if(seeds.isEmpty())break;int created=0;
    for(var seed:seeds.entrySet()){
     var a=seed.getKey();disassemble(a);Function f=createFunction(a,"CANDIDATE_CALL_"+a.toString().replace(':','_'));
     p.println(round+"\t"+a+"\t"+seed.getValue()+"\t"+(f!=null));if(f!=null){created++;total++;}
    }
    if(created==0)break;
   }
  }
  println("DIRECT_CALL_ENTRIES_CREATED "+total);
 }
}
